$string['settings:prompt_debug_enabled']      = 'Log assembled system prompt to file';
$string['settings:prompt_debug_enabled_desc'] = 'When on, every chat-turn writes the full assembled system prompt and per-section character counts to <code>moodledata/temp/sola_prompt_debug.log</code> (rolling at ~1MB). Default off. Use to measure prompt size empirically and audit which sections contribute the most tokens. The log contains the system prompt only (no learner input or PII).';
$string['settings:socratic_verbose'] = 'Lavea sokraattisen tilan kehote';
$string['settings:socratic_verbose_desc'] = 'Kun tämä on päällä, sokraattisen tilan kurssit saavat täyden, noin 600 tokenin tee/älä tee -ohjeen, joka lisättiin alun perin versiossa v3.9.30. Kun tämä on pois (oletus), ne saavat yhden rivin ohjeen, jota nykyaikaiset isännöidyt mallit noudattavat luotettavasti ja joka säästää noin 600 tokenia vuoroa kohden. Kytke tämä päälle, jos kurssi toimii heikommalla itse isännöidyllä mallilla, joka tarvitsee nimenomaisen tukirakenteen.';
$string['settings:prompt_budget_chars'] = 'Järjestelmäkehotteen merkkibudjetti';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = 'Nykyisen sivun sisällön yläraja (merkkiä)';
$string['settings:current_page_content_maxchars_desc'] = 'Nykyisen sivun tekstin enimmäismerkkimäärä, joka lisätään järjestelmäkehotteeseen "Nykyisen sivun sisältö" -osiona, kun RAG on pois päältä. Oletusarvo 8,000 pohjustaa sivukohtaisia kysymyksiä hyvin jättäen samalla budjettia rakenteelle ja ohjeille. (Kun RAG on käytössä, sivu pohjustetaan sen sijaan sen omilla olennaisimmilla osioilla, nykyiseen sivuun painottuen, joten tämä raja ei päde.) Hyvin pitkä sivu typistetään alusta tähän merkkimäärään, joten erittäin pitkän sivun loppua ei ehkä lainata; RAG:n käyttöönotto välttää sen. Kustannustietoiset sivustot voivat rajata alemmas (esim. 3,000-4,000). Rajattu väliin 500-8,000. Riippumaton asetuksesta <code>prompt_budget_chars</code>: tämä rajaa vain sivuosion; budjetti rajaa koko kehotteen.';
$string['settings:prompt_verbosity'] = 'Kehotteen laveus';
$string['settings:prompt_verbosity_desc'] = 'Ohjelohkojen (sokraattinen tila, ulkoiset resurssit) oletuslaveus. Tiivis (oletus) on se, jota nykyaikaiset isännöidyt mallit noudattavat luotettavasti; vakio lisää nimenomaisen tukirakenteen keskitason malleille; lavea säilyttää raskaan v3.9.30-aikaisen ohjeistuksen heikommille itse isännöidyille malleille. Kurssikohtainen ohitus on käytettävissä asetuksella <code>prompt_verbosity_course_&lt;id&gt;</code>.';
$string['settings:prompt_verbosity_concise'] = 'Tiivis (suositus isännöidyille malleille)';
$string['settings:prompt_verbosity_standard'] = 'Vakio';
