$string['empathy:title'] = 'Empaattinen viestintä ja siirtyvä muisti (v5.3.0)';
$string['empathy:desc'] = 'Kolme yhteen sovitettua ominaisuutta, jotka saavat [[tutorshort]]:n tuntumaan enemmän valmentajalta, joka kuuntelee. Tavoitteet kertovat, miksi oppija on täällä. Siirtyvä muisti muistaa, mikä on aiemmin ollut vaikeaa, jotta [[tutorshort]] voi tarjota toisenlaisen näkökulman. Virstanpylväät juhlistavat putkia ja suorituksia sähköpostitse. Jokaisella ominaisuudella on oma katkaisimensa ja oppijan oma suostumus. Vaikeuksien signaalit eivät koskaan poistu keskustelusta — vaikeasta istunnosta ei koskaan lähetetä sähköpostia.';
$string['empathy:outreach_master_enabled'] = 'Tavoittamisen pääkatkaisin';
$string['empathy:outreach_master_enabled_desc'] = 'Uudessa asennuksessa oletuksena pois päältä. Kun tämä on pois, MITÄÄN empaattista sähköpostia ei lähetetä koskaan, riippumatta alla olevista ominaisuuskohtaisista kytkimistä. Kytke tämä päälle vasta, kun olet käynyt läpi ominaisuuskohtaiset oletusarvot ja oppijakohtaisen suostumuksen kulun.';
$string['empathy:goals_enabled'] = 'Ota uratavoitekeskustelut käyttöön';
$string['empathy:goals_enabled_desc'] = 'Antaa oppijoiden kertoa halutessaan kaksi lyhyttä vastausta (miksi he ovat täällä, millaisiksi he haluavat tulla), jotka syötetään personointiin. Vain keskustelussa; ei sähköposteja. Tämän voi turvallisesti jättää päälle.';
$string['empathy:milestones_enabled'] = 'Ota virstanpylväiden pohdintasähköpostit käyttöön';
$string['empathy:milestones_enabled_desc'] = 'Lähettää lyhyen lämpimän sähköpostin, kun oppija saavuttaa 7 päivän putken, 30 päivän putken tai suorittaa kurssin. Vaatii yllä olevan pääkytkimen sekä oppijakohtaisen suostumuksen. Ehdoton yläraja on yksi sähköposti oppijaa kohden 7 päivässä kaikki kanavat yhteenlaskettuna.';
$string['empathy:memory_enabled'] = 'Ota siirtyvä personointimuisti käyttöön';
$string['empathy:memory_enabled_desc'] = 'Antaa [[tutorshort]]:n kuljettaa istunnosta toiseen pieniä yksityisiä muistiinpanoja siitä, mikä on ollut oppijalle vaikeaa, jotta seuraava vastaus voi tarjota toisenlaisen näkökulman. Rajattu (enintään 5 muistiinpanoa oppijaa ja kurssia kohden, 90 päivän elinikä). Oppija voi muokata niitä. Eivät näy koskaan ohjaajille.';
$string['empathy:struggle_enabled'] = 'Ota vaikeuksien luokitin käyttöön';
$string['empathy:struggle_enabled_desc'] = 'Oletuksena pois päältä. Antaa [[tutorshort]]:n havaita pitkittyneen turhautumisen useiden vuorojen aikana ja kirjata hiljaisesti solmukohtaa koskevan muistiinpanon yllä olevaan siirtyvään muistiin. Tulos näkyy vain keskustelussa; vaikeasta istunnosta ei lähetetä koskaan sähköpostia. Poistaa signaalidatan automaattisesti 7 päivän kuluttua.';
$string['empathy:outreach_dryrun'] = 'Tavoittamisen testiajo (kirjaa lähettämättä)';
