$string['settings:prompt_proportions_heading'] = 'Promptin osioiden suhteet (v5.6.0)';
$string['settings:prompt_proportions_heading_desc'] = 'Jaa järjestelmäpromptin budjetti neljään lokeroon: turvallisuus + identiteetti, kurssin rakenne, kurssin sisältö ja nykyinen sivu. Painot ovat prosentteja, joiden summa on 100. Empiirisesti viritetyt oletusarvot (10 / 10 / 40 / 40) ovat peräisin v5.6.0-painojen viritysvertailusta; tekstialueen tyhjäksi jättäminen käyttää näitä oletusarvoja. Automaattinen vahvistus säätää allokaatiota vuorokohtaisesti sen mukaan, onko tietty sivu laajuudessa.';
$string['settings:prompt_section_weights'] = 'Perusosion painot (JSON)';
$string['settings:prompt_section_weights_desc'] = 'Valinnainen JSON-objekti, joka yhdistää jokaisen lokeron prosenttiin. Jätä tyhjäksi käyttääksesi vertailun oletusarvoja (10 / 10 / 40 / 40). Esimerkki: <code>{"safety_identity": 10, "course_structure": 10, "course_content": 40, "current_page": 40}</code>. Painojen summan on oltava 100 (±5%). <code>safety_identity</code>:llä on 10%:n lattia, jotta jailbreak-vastustuskyky ja tulosmuotomarkkerit päätyvät aina täysimääräisinä. <code>current_page + course_content</code>:n on oltava vähintään 40%, jotta mallilla on olennaista materiaalia mihin ankkuroitua. Alueen ulkopuolelle jäävät arvot palaavat hiljaa vertailun oletusarvoihin; ylläpitäjien tulee tarkistaa ne prompt-vianetsintälokista tallennuksen jälkeen.';
$string['settings:prompt_context_boost_mode'] = 'Kontekstin vahvistustila';
$string['settings:prompt_context_boost_mode_desc'] = 'Automaattinen säätö, joka siirtää painoa nykyisen sivun osioon, kun tietty sivu on laajuudessa, ja kurssin sisältöön, kun sivua ei ole valittu. <strong>page_focus</strong> (oletus) siirtää noin 15 painopistettä. <strong>aggressive</strong> siirtää 25 pistettä ja on paras, kun oppijat esittävät johdonmukaisesti sivukohtaisia kysymyksiä. <strong>off</strong> poistaa vahvistuksen käytöstä; ylläpitäjän asettamat perusarvot koskevat kaikkia vuoroja siivukontekstista riippumatta.';
$string['settings:prompt_context_boost_off'] = 'Pois päältä (käytä perusarvoja jokaisessa vuorossa)';
$string['settings:prompt_context_boost_page_focus'] = 'Sivukohdistus (oletus, ~15 pisteen siirto)';
$string['settings:prompt_context_boost_aggressive'] = 'Aggressiivinen (~25 pisteen siirto)';
$string['settings:prompt_section_weights_coach'] = 'Valmentajatilan ohitus (JSON, valinnainen)';
$string['settings:prompt_section_weights_coach_desc'] = 'Valinnainen JSON-objekti, joka ohittaa perusosion painot erityisesti arvostellun tentin valmentajatilan aikana (kun <code>quizmode=coach</code>). Hyödyllinen pakottamaan raskaampi <code>current_page</code>-allokaatio tenttien aikana vaikuttamatta normaaliin chattiin. Jätä tyhjäksi periäksesi perusarvot. Samat vahvistussäännöt kuin perusasetuksessa.';
