$string['settings:mastery_classifier_provider'] = 'Luokittelijan palveluntarjoaja';
$string['settings:mastery_classifier_provider_desc'] = 'Palveluntarjoajan tunnus, jota käytetään vuorokohtaisessa hallintamatriisin luokittelijassa. Jätä tyhjäksi periäksesi oletusarvoisen AI-palveluntarjoajan. Oletus <code>openai</code> toimii alla olevan <code>gpt-4o-mini</code>-luokittelijamallin kanssa — halvin TIER 1 -vaihtoehto rakenteellisen tulosteen luokitteluun (~$220/kk säästöä 100k MAU:lla vs chat-tason). Kun asetettu, Vertailupalveluntarjoajat-rivin tämä palveluntarjoajatunnus tarjoaa API-avaimen, perus-URL:n ja lämpötilan.';
$string['settings:premium_escalation_heading'] = 'Premium-eskalointitaso (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'Valinnainen vuorokohtainen reititys premium-mallille (oletuksena Claude Opus 4.8) prompteille, joissa työtason chat näkyvästi kamppailee — tyypillisesti monivaiheinen matematiikka, CS ja tieteellinen päättely. Ratkaistu 26.6.2026 A.10-paistamisessa: Opus 4.8 voitti tuloksella 14,97/15 vs gpt-4o:n 12,68/15 vaikeissa prompteissa. Kaksi aktivointireittiä: regex-vastaavuudet käyttäjäviestissä TAI kurssin sallittujen lista, joka eskaloi jokaisen vuoron. Oletuksena pois päältä. ~5%:n eskaloinnilla odota ~$700/kk 100k [[unishort]] MAU:lla perustason chat-kulujen lisäksi.';
$string['settings:premium_escalation_enabled'] = 'Ota premium-eskalointireititys käyttöön';
$string['settings:premium_escalation_enabled_desc'] = 'Kun käytössä, vuorokohtainen reititin tarkistaa aktivointi-regex-listan ja kurssin sallittujen listan jokaisen chat-kutsun osalta; vastaavat vuorot reititetään premium-palveluntarjoajalle. Palaa työn palveluntarjoajalle, jos premium-rivi puuttuu tai ei voi instantioitua. Ylläpitäjän LLM-valitsimen ohitukset voittavat aina riippumatta.';
$string['settings:premium_escalation_provider'] = 'Premium-palveluntarjoaja';
$string['settings:premium_escalation_provider_desc'] = 'Palveluntarjoajan tunnus, jonka kautta premium-kutsut reititetään. Täytyy vastata Vertailupalveluntarjoajat-rivin tunnusta (jotta API-avain, perus-URL ja lämpötila tulevat samasta paikasta, jota ylläpitäjät jo hallitsevat). Oletus <code>claude</code>.';
$string['settings:premium_escalation_model'] = 'Premium-malli';
$string['settings:premium_escalation_model_desc'] = 'Mallin nimi välitettäväksi premium-palveluntarjoajalle. Oletus <code>claude-sonnet-5</code> A.10-paistamisen tuomion mukaan.';
$string['settings:premium_escalation_triggers'] = 'Premium-aktivointi-regexlit';
$string['settings:premium_escalation_triggers_desc'] = 'Yksi PCRE-regex per rivi (ilman erottimia; kirjainkoosta riippumaton vastaavuus sovelletaan automaattisesti). # -merkillä alkavat rivit ovat kommentteja. Jätä tyhjäksi käyttääksesi A.10-paistamisen valittua oletusarvojoukkoa (monivaiheisen STEMin markkerit: "derive", "prove that", "step by step", LaTeX math, aidatut koodilohkot, big-O, integraalit, optimointi jne.).';
$string['settings:premium_escalation_course_tags'] = 'Kurssin sallittujen lista premiumille';
$string['settings:premium_escalation_course_tags_desc'] = 'Yksi kurssin lyhytnimi tai idnumber-etuliite per rivi. Jokainen vuoro vastaavalla kurssilla eskaloidaan automaattisesti riippumatta viestin regexistä (käytä STEM-painotteisilla kursseilla, joilla eskalointia tulisi olla oletuksena). Vastaavuus on kirjainkoosta riippumaton etuliite — "MATH" vastaa MATH121, MATH205 jne.';
$string['settings:spend_cap_per_course_default'] = 'Oletusarvoinen kurssikohtainen kuluraja (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'Puolustuksellinen raja sovellettuna jokaiseen kurssiin, jolla ei ole omaa kurssikohtaista kulurajaa konfiguroitu. Aseta esim. <code>30</code> rajoittaaksesi yksittäisen kurssin kuukausittaiset kulut $30:een ilman yksittäisten kurssien virittämistä. <code>0</code> = ei oletusrajaa (vain sivustonlaajuiset ja kurssikohtaiset ohitusrajat soveltuvat). Kun kurssi ylittää 80% / 95% / 100% tästä rajasta, olemassa oleva spend-guardin hälytyksien liukuhihna lähettää ylläpitäjän ilmoituksen (vastaanottajalista: <code>spend_notify_emails</code>, palaa sivuston ylläpitäjille). Tietty kurssi voi aina nostaa omaa kattoaan asettamalla korkeamman kurssikohtaisen ohituksen.';
$string['settings:cost_anomaly_heading'] = 'Kustannuspoikkeavuuden ilmaisin (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'Päivittäinen ajastettu tehtävä (<code>cost_anomaly_check</code>), joka vertaa tämän päivän sivustonlaajuisia [[tutorshort]]-kuluja 7 päivän liukuvaan mediaaniin. Lähettää sähköpostia <code>spend_notify_emails</code>-vastaanottajalistalle (palaa sivuston ylläpitäjille), kun tämän päivän kulut ylittävät konfiguroitu kerroin × mediaani. Havaitsee kolme vikatilaa, jotka olemassa olevat 80% / 95% / 100% kulurajan kynnysarvot eivät havaitse: (1) raju kurssi, jossa absoluuttista kattoa ei ylitetä mutta yksittäinen kurssi ajaa äkillisesti 10-kertaisen tavallisen volyyminsa, (2) vahingollinen premium-tason käyttöönotto, (3) palveluntarjoajan virheellinen reititys. Oletuksena pois päältä; [[tutorshort]]:n sisäinen vastine Redash-kyselylle osoitteessa <code>.drafts/sola-redash-cost-anomaly-2026-06-09.md</code>.';
$string['settings:cost_anomaly_enabled'] = 'Ota kustannuspoikkeavuuden ilmaisin käyttöön';
$string['settings:cost_anomaly_enabled_desc'] = 'Kun käytössä, päivittäinen ajastettu tehtävä arvioi tämän päivän kulut 7 päivän liukuvaan mediaaniin nähden ja lähettää ylläpitäjille sähköpostia poikkeavuuden yhteydessä. Ensimmäiset 7 päivää käyttöönoton jälkeen tuottavat <code>insufficient_history</code>-tilan (ei vielä historiallista perustasoa) eikä koskaan lähetä hälytystä. Idempotentinen päivää kohden: lippu <code>config_plugins</code>-taulussa estää toistuvia sähköposteja, jos cron ajaa useita kertoja.';
$string['settings:cost_anomaly_multiplier'] = 'Poikkeavuuskerroin';
$string['settings:cost_anomaly_multiplier_desc'] = 'Tämän päivän kulujen on ylitettävä tämä kerroin × 7 päivän mediaani hälytyksen käynnistämiseksi. Oletus <code>2.0</code>. Laske arvoon <code>1.5</code> aiempia varoituksia varten (enemmän vääriä positiivisia ilmoittautumispiikkien aikana). Nosta arvoon <code>3.0</code>, jos [[unishort]]-käyttö on niin vaihtelevaa, että 2x piikit ovat tavanomaisia.';
$string['task:cost_anomaly_check'] = '[[tutorshort]]:n kustannuspoikkeavuuden tarkistus (päivittäinen)';

