$string['settings:rag_pdftotext_path'] = 'pdftotext-ohjelman polku';
$string['settings:rag_pdftotext_path_desc'] = 'Jätä tyhjäksi automaattista tunnistusta varten (tarkistaa <code>/usr/bin/pdftotext</code>, <code>/usr/local/bin/pdftotext</code> ja <code>which pdftotext</code>). Täytä tämä vain, jos asennuksesi sijaitsee muualla.';
$string['settings:rag_extract_docx'] = 'Indeksoi DOCX-tiedostot (mod_resource)';
