$string['settings:rag_extract_h5p'] = 'Indeksoi H5P-sisältö (mod_h5p)';
$string['settings:rag_extract_h5p_desc'] = 'Käy läpi H5P-sisällön JSON-rakenteen ja indeksoi kaikki tekstiä sisältävät kentät (kysymykset, vastaukset, palautteet, kuvaukset). H5P-sisältötyyppien metatiedot ovat laajat; rajatapauksissa on odotettavissa yksittäisiä virheosumia.';
$string['settings:rag_extract_scorm'] = 'Indeksoi SCORM-paketit (mod_scorm)';
