$string['settings:rag_scorm_max_mb'] = 'Indeksoitavan SCORM-paketin enimmäiskoko (Mt)';
$string['settings:rag_scorm_max_mb_desc'] = 'Ohittaa tätä suuremmat SCORM-paketit liiallisen muistinkäytön välttämiseksi.';
$string['settings:rag_fetch_transcripts'] = 'Hae tekstivastineet upotetuille videoille ja vuorovaikutteiselle sisällölle';
$string['settings:rag_fetch_transcripts_desc'] = 'Käy läpi mod_pagen ja mod_bookin sisällön etsien upotettuja iframe-kehyksiä (Synthesia, YouTube, Articulate, Genially) ja hakee kuhunkin upotukseen liittyvän tekstivastineen URL-osoitteen (haku tehdään sekä kehyksen ylä- että alapuolelta). Edellyttää lähtevää HTTPS-yhteyttä tältä palvelimelta tekstivastineiden palvelimelle. <strong>Pois käytöstä oletuksena</strong>; ota käyttöön, kun tekstivastineiden palvelin on lisännyt tämän palvelimen sallittujen luetteloonsa (esimerkiksi Cloudflaren IP-käyttösäännöllä).';
$string['settings:rag_iframe_host_patterns'] = 'Iframe-palvelinten hakumallit';
$string['settings:rag_iframe_host_patterns_desc'] = 'Yksi säännöllinen lauseke riviä kohden, joka vastaa iframe-kehyksen <code>src</code>-määritettä. Jokainen osuva kehys käsitellään vuorovaikutteisena upotuksena, jonka tekstivastine tulee liittää ja indeksoida. Rivit, jotka alkavat merkillä <code>#</code>, ovat kommentteja.';
$string['settings:rag_transcript_url_pattern'] = 'Tekstivastineen URL-hakumalli';
