$string['settings:spend_guard_heading'] = 'Kulusuojaus ja optimoija';
$string['settings:spend_guard_heading_desc'] = 'Aseta LLM-kulukatot jaksoa kohden. Kun katto täyttyy, [[tutorshort]] keskeyttää pyynnöt tai siirtyy edullisempaan palveluntarjoajaan varajärjestelyketjustasi. Katso <a href="{$a}">Tokenkustannukset-sivulta</a> nykyinen kulutilanne ja optimoijan suositukset.';
$string['settings:spend_cap_period'] = 'Kulukaton jakso';
