$string['settings:spend_failover_chain'] = 'Varajärjestelyketju';
$string['settings:spend_failover_chain_desc'] = 'Kun katto täyttyy, [[tutorshort]] kokeilee näitä palveluntarjoajia järjestyksessä. Yksi merkintä riviä kohden muodossa <code>capability:label</code>. Nimikkeet viittaavat Vertailupalveluntarjoajien merkintöihin (kohteille <code>chat</code> / <code>analytics</code>) tai Puhepalveluntarjoajien merkintöihin (kohteelle <code>voice</code>). Rivit, jotka alkavat merkillä <code>#</code>, ovat kommentteja. Esimerkki:<br><code>chat:claude-haiku<br>chat:ollama-local<br>voice:openai-prod<br>analytics:deepseek</code>';
$string['settings:failover_per_call_enabled'] = 'Kutsukohtainen varajärjestely (v5.5.0)';
$string['settings:failover_per_call_enabled_desc'] = 'Kun tämä on käytössä, jokainen chat-kutsu kietoo ensisijaisen palveluntarjoajan varajärjestelyketjun kuoreen. Jos kutsu aikakatkaistaan tai palauttaa 5xx-virheen, [[tutorshort]] siirtyy yllä olevan <strong>varajärjestelyketjun</strong> seuraavaan merkintään ja avaa vikaantuneelle palveluntarjoajalle 15 minuutin katkaisijan. Jokaisesta siirtymästä kirjataan valvontarivi (<code>failover_fallthrough</code>); tarkista käyttöönoton jälkeen Ylläpito -> [[tutorshort]] -> Valvontaloki varmistaaksesi, että ketju toimii. Pois käytöstä oletuksena; ota käyttöön vasta, kun ketju on validoitu ja organisaatiosi on varmistanut, että jokaisen ketjun palveluntarjoajan kanssa on tarvittavat tietojenkäsittelysopimukset.';
$string['settings:failover_timeout_chat'] = 'Kutsukohtainen varajärjestely: chatin aikakatkaisu (sekuntia)';
$string['settings:failover_timeout_chat_desc'] = 'Kuinka kauan chat-palveluntarjoajan ensimmäistä tokenia odotetaan ennen siirtymistä. Oletus 8 s. Pienemmät arvot siirtyvät nopeammin hitaiden palveluntarjoajien kohdalla, mutta aiheuttavat vääriä osumia tilapäisesti hitaissa pyynnöissä; suuremmat arvot pitävät ketjun pidempään ensisijaisessa palveluntarjoajassa. Otetaan huomioon vain, kun <strong>kutsukohtainen varajärjestely</strong> on käytössä.';
$string['settings:spend_notify_emails'] = 'Kuluhälytysten vastaanottajat';
$string['settings:spend_notify_emails_desc'] = 'Pilkuilla erotetut sähköpostiosoitteet, joille ilmoitetaan katon täyttyessä 80, 95 ja 100 prosenttiin. Jätä tyhjäksi ilmoittaaksesi kaikille sivuston ylläpitäjille.';
$string['settings:opt_cost_weight'] = 'Optimoija: kustannuksen painoarvo';
$string['settings:opt_cost_weight_desc'] = 'Kuinka paljon optimoija painottaa kustannuksia palveluntarjoajia järjestettäessä. 0.0 jättää kustannukset huomiotta, 1.0 optimoi pelkästään kustannusten mukaan. Otetaan huomioon yhdessä laadun painoarvon kanssa.';
$string['settings:opt_quality_weight'] = 'Optimoija: laadun painoarvo';
$string['settings:opt_quality_weight_desc'] = 'Kuinka paljon optimoija painottaa opiskelijoiden tyytyväisyyttä (peukku ylös -osuutta) palveluntarjoajia järjestettäessä. 0.0 jättää laadun huomiotta.';
$string['settings:inactivity_reminder_enabled'] = 'Muistutukset toimettomuudesta';
$string['settings:inactivity_reminder_enabled_desc'] = 'Lähettää viikoittaisen sähköpostin opiskelijoille, jotka eivät ole avanneet kurssiaan määritettyyn päivämäärään mennessä.';
$string['settings:inactivity_threshold_days'] = 'Toimettomuuden raja (päivää)';
$string['settings:inactivity_threshold_days_desc'] = 'Toimettomuuspäivien määrä ennen muistutussähköpostin lähettämistä.';
$string['settings:voice_providers_heading'] = 'Puhepalveluntarjoajat (Realtime, TTS, STT)';
$string['settings:voice_providers_heading_desc'] = 'Määritä yksi tai useampi puherajapinnan palveluntarjoaja. Nämä asetukset ovat riippumattomia yllä olevasta chat-palveluntarjoajasta ja RAG:n upotuspalveluntarjoajasta — puheella on oma palveluntarjoajaluettelonsa, koska tällä hetkellä vain OpenAI ja xAI tarjoavat WebSocket-pohjaiset Realtime-, TTS- ja STT-päätepisteet. Valitse alla olevista valikoista, mikä rekisteröity palveluntarjoaja hoitaa kunkin toiminnon. Jos rivejä ei ole määritetty, käytetään vanhaa yhden avaimen menettelyä (yllä oleva Realtime API -avain tai ensisijainen OpenAI-avain). Sivuston, joka käyttää chatissa palveluita Together AI / Anthropic / DeepSeek / Gemini / Mistral, on määritettävä tähän vähintään yksi rivi, jotta puhe toimii.';
$string['settings:voice_active_realtime'] = 'Aktiivinen Realtime-palveluntarjoaja';
