$string['settings:voice_active_stt'] = 'Aktiivinen STT-palveluntarjoaja';
$string['settings:voice_active_stt_desc'] = 'Mikä palveluntarjoaja muuntaa opiskelijoiden puheen tekstiksi. Jätä tyhjäksi, jos haluat ensisijaisesti käyttää alla määritettyä itse ylläpidettyä Whisper-palvelinta ja sen jälkeen ensimmäistä puhepalveluntarjoajariviä tai vanhaa avainta.';
$string['settings:stt_selfhosted_enabled'] = 'Ota käyttöön itse ylläpidetty puheentunnistus';
