$string['settings:bench_min_quality_n_desc'] = 'Pienin määrä pisteytettyjä kohteita, joka tallennetulla ajolla voi olla ja jota voi silti verrata toiseen ajoon. Alarajan alittavat ajot säilytetään ja näytetään merkittynä vain viitteeksi, joten kolmen kehotteen savutesti ei voi koskaan päihittää viidenkymmenen kehotteen tulosta. Jätä arvoon 0 käyttääksesi sisäänrakennettua oletusta; alaraja 0 mitätöisi suojauksen.';
$string['settings:embed_input_type_asymmetric'] = 'Epäsymmetrinen kysely/dokumentti (suositeltu)';
$string['settings:embed_input_type_mode'] = 'Upotuksen syötetyyppi';
$string['settings:embed_input_type_mode_desc'] = 'Vain Voyage-upotuksille. Voyage projisoi tekstin eri tavalla sen mukaan, onko kyseessä kysely vai dokumentti. "Epäsymmetrinen" lähettää input_type=query haettaessa ja input_type=document indeksoitaessa. Näin toimittaja on tarkoittanut, ja se mittaa parhaiten tässä korpuksessa: dokumenttiprojektion käyttö kyselypuolella maksoi 30,8 prosenttiyksikköä recallia ja hävisi kaikissa kyselyn pituusluokissa (2026-08-21, voyage-3.5, tuotannonmukainen joukko). "Jaettu avaruus" lähettää input_type=document molemmille puolille; se hakee mitattavasti huonommin ja on olemassa vain migraatiovakuutuksena, koska yksi projektio sallii kyselymallin vaihtamisen ilman korpuksen uudelleenupottamista. Valitse epäsymmetrinen, ellet ole kesken migraation. Tämän muuttaminen ei vaadi uudelleenindeksointia: vain kyselypuolen projektio muuttuu. Tämä EI ole epäsymmetrinen mallien parittaminen (indeksointi suuremmalla Voyage-mallilla kuin sillä, jolla kysytään) – se on eri tekniikka, joka ei toistunut tässä korpuksessa kahdesti, ja sitä ohjaa kyselymallin asetus, ei tämä.';
$string['settings:embed_input_type_shared'] = 'Jaettu avaruus (migraatiovakuutus; hakee huonommin)';
$string['settings:embed_migration_heading'] = 'Upotusmallin siirto';
$string['settings:embed_migration_heading_desc'] = 'Upotusmallin tai sen leveyden vaihtaminen mitätöi jokaisen tallennetun vektorin: haku kieltäytyy pisteyttämästä kyselyä sellaisia lohkoja vasten, jotka ovat eri upotusavaruudesta, joten kurssi ei hae mitään sen sijaan, että hakisi huonosti. Nämä asetukset kuvaavat mallia, JOHON olet siirtymässä. Kurssit upotetaan sen jälkeen uudelleen yksi kerrallaan RAG-indeksisivulta, ja uudet vektorit kirjoitetaan vanhojen rinnalle; yllä olevat käytössä olevat asetukset palvelevat hakua, kunnes vaihdat ne itse.';
$string['settings:embed_migration_provider_inherit'] = 'Käytä yllä määritettyä tarjoajaa';
$string['settings:embed_migration_target_apikey'] = 'Kohdetarjoajan API-avain';
$string['settings:embed_migration_target_apikey_desc'] = 'Tarvitaan vain, kun kohdetarjoaja on eri kuin yllä määritetty. Tyhjä tarkoittaa, että käytetään nykyistä upotusavainta.';
$string['settings:embed_migration_target_dimensions'] = 'Kohdeupotuksen leveys';
$string['settings:embed_migration_target_dimensions_desc'] = 'Vektorin leveys, jota siirron aikana pyydetään. 0 tarkoittaa mallin omaa leveyttä. Voyage hyväksyy arvot 256, 512, 1024 ja 2048; leveys jota malli ei tarjoa jätetään pyynnöstä pois sen sijaan, että se lähetettäisiin, mikä antaisi sinulle huomaamatta mallin oman leveyden pyytämäsi sijaan.';
$string['settings:embed_migration_target_model'] = 'Kohdeupotusmalli';
$string['settings:embed_migration_target_model_desc'] = 'Mallin nimi, jolla siirron aikana upotetaan, esimerkiksi <code>voyage-4-large</code>. Tyhjä tarkoittaa, ettei siirtoa ole määritetty eikä RAG-indeksisivu tarjoa sitä.';
$string['settings:embed_migration_target_provider'] = 'Kohdeupotusten tarjoaja';
$string['settings:embed_migration_target_provider_desc'] = 'Jätä tyhjäksi siirtääksesi jo yllä määritetyn tarjoajan sisällä.';
$string['settings:rerank_min_query_chars'] = 'Uudelleenjärjestys: kyselyn vähimmäispituus';
$string['settings:rerank_min_query_chars_desc'] = 'Ohita uudelleenjärjestäjä kyselyillä, jotka ovat enintään näin monta merkkiä pitkiä. Lyhyet kyselyt ovat avainsanamaisia, ja uudelleenjärjestäjä ei lisää kahdella tai kolmella sanalla käytännössä mitään kosinisimilaarisuuden päälle. Mitattu RAG-testiaineistolla: portti arvossa 50 sai saantitarkkuuden 67,7 % vastaan 67,2 % aina päällä olevalle, noin kolmanneksella kustannuksista. Aseta arvoon 0 järjestääksesi jokaisen kyselyn uudelleen. Ohitetut uudelleenjärjestykset kirjataan viestilokiin muodossa "[Rerank skipped: short_query]", joten voit varmistaa portin toimivan.';
$string['settings:spend_export_key'] = 'Kuluviennin avain';
$string['settings:spend_export_key_desc'] = 'Bearer-avain kuukausittaiselle tekoälykulujen vientipäätepisteelle osoitteessa <code>/local/ai_course_assistant/spend_export.php</code>, jonka kulupaneeli noutaa kerran kuussa. Jätä tyhjäksi kytkeäksesi päätepisteen pois — se palauttaa silloin 404 jokaiseen pyyntöön. Avain hyväksytään VAIN <code>Authorization: Bearer</code> -otsakkeessa, ei koskaan URL-osoitteessa. Luo pitkä satunnainen arvo; jokainen sen haltija voi lukea koko sivuston tekoälykulut. Jokainen onnistunut vienti kirjataan lisäosan auditlokiin.';
